// Tests like the ones in class for American History, three questions each: 1. key words, people and dates (match them,
// put events in order, work out the years between) or the timeline, 2. a source to read and question, and 3. an
// extended answer that explains causes or results. The sources are made up for these tests, in the style of the time,
// and each says so; every fact in them and in the mark schemes is the usual one in school histories, and where
// historians disagree (how many died, why a choice was made) the words say so. kit/exam-kit.js says what a question
// and its parts are.
import { examBank } from '../kit/exam-kit.js';
import { num } from '../kit/bank.js';
import { TOPICS, near } from './us-history-data.js';

const TIMELINE = TOPICS.flatMap((t) => t.events.map((e) => ({ ...e, topic: t.name })));
const PLACES = ['1st', '2nd', '3rd', '4th', '5th'];
const ordinal = (n) => n + (n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');
const century = (y) => Math.floor((y - 1) / 100) + 1;
const inCentury = (y) => `${y} is in the ${ordinal(century(y))} century (${y % 100 ? 'its hundreds plus one' : 'the last year of it'}).`;
// four events at least `gap` years from each other, so the order and the years between are fair to ask: from anywhere on
// the timeline, which spans five centuries, so there are always enough (closer together only if a timeline were short)
function spread(d, gap, from = TIMELINE) {
  const out = [];
  for (const e of d.shuffle(from)) if (out.length < 4 && out.every((p) => Math.abs(p.y - e.y) >= gap)) out.push(e);
  return out.length === 4 || gap <= 1 ? out : spread(d, gap / 2, from);
}
// five topics no two of them close in time (near), so a name can't fit another one's meaning, and a pair from each with
// no meaning twice
function matching(d) {
  const topics = [], pairs = [];
  for (const t of d.shuffle(TOPICS)) if (topics.length < 5 && topics.every((u) => !near(u.name, t.name))) topics.push(t);
  for (const t of d.shuffle(TOPICS)) if (topics.length < 5 && !topics.includes(t)) topics.push(t);
  for (const t of topics) {
    const p = d.shuffle(t.pairs).find((x) => pairs.every((y) => y[0] !== x[0] && y[1] !== x[1]));
    if (p) pairs.push(p);
  }
  return pairs;
}
const sourceBox = (who, text) => `<p><b>Source A</b></p><blockquote class="source"><p>${text}</p><footer>${who}</footer></blockquote>`;
const MADE_UP = '<p class="muted small">Source A was written for this test, in the style of the time. It is not a real document.</p>';

// ---------- 1. key words, people and dates ----------
// five people, places or words from five topics far apart, each matched to what it was; four events put in order; and
// one fact question
function keyWords(d) {
  const pairs = matching(d), meanings = d.shuffle(pairs.map((p) => p[1]));
  const events = spread(d, 10), sorted = events.slice().sort((a, b) => a.y - b.y);
  const t = d.pick(TOPICS), [q, right, wrong, why] = d.pick(t.facts);
  const choices = d.shuffle([right, ...d.shuffle(wrong).slice(0, 3)]);
  return {
    title: 'Key words, people and dates',
    intro: '<p>Show what you know about the people, places and ideas of American history, and when things happened.</p>',
    parts: [
      { kind: 'select', ask: 'Match each one to what it was.', fields: pairs.map((p) => ({ label: p[0], options: meanings, correct: meanings.indexOf(p[1]) })),
        working: pairs.map((p) => `${p[0]}: ${p[1]}.`).join(' ') },
      { kind: 'select', ask: 'Put these events in order: choose 1st for the earliest.', fields: events.map((e) => ({ label: e.label, options: PLACES.slice(0, 4), correct: sorted.indexOf(e) })),
        working: `In order: ${sorted.map((e) => `${e.label} (${e.y})`).join(', ')}.` },
      { kind: 'number', ask: `How many years passed between these two events? ${sorted[0].label} (${sorted[0].y}) and ${sorted[3].label} (${sorted[3].y}).`, value: sorted[3].y - sorted[0].y, unit: 'years', tol: { abs: 0 },
        working: `${sorted[3].y} − ${sorted[0].y} = ${num(sorted[3].y - sorted[0].y)} years.` },
      { kind: 'choice', ask: q, choices, correct: choices.indexOf(right), topic: t.name, working: why },
    ],
  };
}
// the timeline: four events placed in their centuries, the gap between two of them, and which era one belongs to. It
// asks about events from 1401 to 1991, so each one's century is among the choices (15th to 20th) and its era is one of
// the four
const ERAS = ['Colonies and revolution: to 1783', 'A new nation, growing and dividing: 1784 to 1860', 'The Civil War, rebuilding and a modern nation: 1861 to 1913', 'World wars, the Depression and the Cold War: 1914 to 1991'];
const eraOf = (x) => (x.y <= 1783 ? 0 : x.y <= 1860 ? 1 : x.y <= 1913 ? 2 : 3);
const DATED = TIMELINE.filter((x) => x.y > 1400 && x.y <= 1991);
function timeline(d) {
  const events = spread(d, 20, DATED), options = [15, 16, 17, 18, 19, 20].map((c) => `${ordinal(c)} century`);
  const [a, b] = d.shuffle(events).slice(0, 2).sort((x, y) => x.y - y.y);
  const e = d.pick(events), era = eraOf(e), same = d.shuffle(DATED.filter((x) => x.y !== e.y && eraOf(x) === era));
  return {
    title: 'The timeline',
    intro: '<p>American history up to 1991 can be split into four eras: <b>colonies and revolution</b> (to 1783), <b>a new nation, growing and dividing</b> (1784 to 1860), <b>the Civil War, rebuilding and a modern nation</b> (1861 to 1913), and <b>world wars, the Depression and the Cold War</b> (1914 to 1991).</p>',
    parts: [
      { kind: 'select', ask: 'In which century did each of these happen?', fields: events.map((x) => ({ label: `${x.label} (${x.y})`, options, correct: options.indexOf(`${ordinal(century(x.y))} century`) })),
        working: events.map((x) => inCentury(x.y)).join(' ') },
      { kind: 'number', ask: `How many years after “${a.label}” (${a.y}) came “${b.label}” (${b.y})?`, value: b.y - a.y, unit: 'years', tol: { abs: 0 },
        working: `${b.y} − ${a.y} = ${num(b.y - a.y)} years.` },
      { kind: 'choice', ask: `In which era was “${e.label}” (${e.y})?`, choices: ERAS, correct: era, topic: e.topic,
        explain: { ask: 'Name one other event from the same era, with its date.', lines: 2, marks: 1,
          points: [`Any event from the same era with roughly the right date, for example ${same.slice(0, 2).map((x) => `${x.label.replace(/^The /, 'the ')} (${x.y})`).join(' or ')}`],
          model: `For example: ${same[0].label} (${same[0].y}).` },
        working: `${e.y} falls in “${ERAS[era]}”.` },
    ],
  };
}

// ---------- 2. a source ----------
// each source: who it's from, its words, what it's about, and the questions on it
function source({ title, topic, who, text, about, aboutWrong, kind, kindWrong, details, useful, model, context }) {
  return (d) => {
    const ab = d.shuffle([about, ...aboutWrong]), ki = d.shuffle([kind, ...kindWrong]);
    return {
      title, intro: `${sourceBox(who, text)}${MADE_UP}`,
      parts: [
        { kind: 'choice', ask: 'Which event is Source A about?', choices: ab, correct: ab.indexOf(about), topic },
        { kind: 'select', ask: 'What kind of source is it?', fields: [{ label: 'Source A is', options: ki, correct: ki.indexOf(kind) }] },
        { kind: 'written', ask: `What can you learn from Source A about ${details.what}? Use <b>two</b> details from the source.`, lines: 4, topic,
          points: details.points, model: details.model, notes: ['Copying the source without saying what it shows earns no marks.'] },
        { kind: 'written', ask: 'Use what you know to explain <b>one</b> thing that was happening at the time of Source A.', lines: 4, topic, marks: 2,
          points: context.points, model: context.model },
        { kind: 'written', ask: `How useful is Source A to a historian studying ${useful}? Think about who wrote it, when, and why.`, lines: 5, topic, marks: 3,
          points: ['Says what the source is useful for, with a detail from it', 'Uses who wrote it, or when, to judge it (an eyewitness, or someone who heard about it later)', 'Says a limit: what it leaves out, or why the writer might be one-sided or exaggerate'],
          model, notes: ['“It is useful because it is a primary source” on its own earns no mark: say why that matters here.'] },
      ],
    };
  };
}
